<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_login();$page_title='Work Orders Request';require __DIR__.'/../includes/header.php';$sql='SELECT r.*,e.equipment_name,u.name reporter FROM maintenance_requests r JOIN equipment e ON e.id=r.equipment_id JOIN users u ON u.id=r.reported_by ORDER BY r.created_at DESC';$rows=$pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);?>
<div class="d-flex justify-content-between mb-4"><div><h1 class="page-heading"><?=e(t('requests'))?></h1><p class="page-subtitle mb-0"><?=current_language()==='zh'?'报告并追踪设备问题。':'Report and track equipment issues.'?></p></div><?php if(can_submit_requests()):?><a class="btn btn-primary" href="add_request.php"><i class="bi bi-plus-lg"></i> <?=e(t('create_request'))?></a><?php endif?></div><div class="panel table-responsive"><table class="table table-hover mb-0"><thead><tr><th><?=e(t('request_id'))?></th><th><?=e(t('equipment'))?></th><th><?=e(t('reported_by'))?></th><th><?=e(t('priority'))?></th><th><?=e(t('status'))?></th><th><?=e(t('date'))?></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['request_code'])?></b><br><small class="text-muted"><?=e(mb_strimwidth($r['problem_description'],0,40,'…'))?></small></td><td><?=e($r['equipment_name'])?></td><td><?=e($r['reporter'])?></td><td><span class="badge status-<?=e($r['priority'])?>"><?=e(tv($r['priority']))?></span></td><td><span class="badge status-<?=str_replace(' ','-',$r['status'])?>"><?=e(tv($r['status']))?></span></td><td><?=date('d M Y',strtotime($r['created_at']))?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/../includes/footer.php'; ?>
